sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float intensity;
layout(color) uniform half4 color;
uniform float blend;
uniform float opacity;
uniform float corners;
uniform float style;
uniform float4 screen;
float4 inFrame(float2 q) {
    return image.eval(style > 0.5 ? clamp(q, screen.xy + 0.5, screen.xy + screen.zw - 0.5) : q);
}
float exitAt(float2 p, float2 u, float r) {
    float lo = 0.0;
    float hi = -1.0;
    for (int i = 1; i <= 12; i++) {
        float s = r * float(i) / 12.0;
        if (float(inFrame(p + u * s).a) < 0.5) {
            hi = s;
            break;
        }
        lo = s;
    }
    if (hi < 0.0) return r;
    for (int i = 0; i < 5; i++) {
        float m = 0.5 * (lo + hi);
        if (float(inFrame(p + u * m).a) < 0.5) hi = m; else lo = m;
    }
    return 0.5 * (lo + hi);
}
float squareDistance(float2 p, float r) {
    float d = r;
    d = min(d, exitAt(p, float2(1.0, 0.0), d));
    d = min(d, exitAt(p, float2(-1.0, 0.0), d));
    d = min(d, exitAt(p, float2(0.0, 1.0), d));
    d = min(d, exitAt(p, float2(0.0, -1.0), d));
    d = min(d, exitAt(p, float2(0.70710678, 0.70710678), d * 1.41421356) * 0.70710678);
    d = min(d, exitAt(p, float2(-0.70710678, 0.70710678), d * 1.41421356) * 0.70710678);
    d = min(d, exitAt(p, float2(0.70710678, -0.70710678), d * 1.41421356) * 0.70710678);
    d = min(d, exitAt(p, float2(-0.70710678, -0.70710678), d * 1.41421356) * 0.70710678);
    return d;
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0 || blur <= 0.0) return src;
    float g = corners > 0.5 ? clamp(intensity * (1.0 - smoothstep(0.0, blur, squareDistance(coord, blur))), 0.0, 1.0)
                            : clamp((1.0 - float(blurred.eval(coord).a)) * 2.0 * intensity, 0.0, 1.0);
    g *= float(color.a) * clamp(opacity, 0.0, 1.0);
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = blend > 0.5 ? mix(base, float3(color.rgb), g) : base + float3(color.rgb) * g - base * float3(color.rgb) * g;
    return half4(half3(rgb) * src.a, src.a);
}
